/*
 * A042876  Numerators of continued fraction convergents to sqrt(970).
 * https://oeis.org/A042876
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, frac, easy
 * Formula:   a(n) = numerator of the n-th convergent of the continued
 *            fraction * expansion of sqrt(970). The sequence is generated by
 *            the standard * recurrence for continued‑fraction convergents
 * Range:     u8 n <= 2, u16 n <= 7, u32 n <= 14, u64 n <= 27, u128 n <= 58,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

seq_t a(idx_t n)
{
    /* Fundamental data for sqrt(970) */
    const idx_t D   = 970;   /* the radicand */
    const idx_t a0  = 31;    /* ⌊sqrt(970)⌋ */

    /* State variables for the continued‑fraction algorithm */
    idx_t m = 0;        /* m_0 */
    idx_t d = 1;        /* d_0 */
    idx_t ak_prev = 0;  /* a_{k-1}, unused for k == 0 */

    /* Convergent numerators: p_-2 = 0, p_-1 = 1 */
    seq_t p_nm2 = 0;
    seq_t p_nm1 = 1;
    seq_t p_cur = 0;

    for (idx_t k = 0; k <= n; ++k)
    {
        idx_t ak;
        if (k == 0)
        {
            ak = a0;
        }
        else
        {
            /* Compute the next m and d using the previous partial quotient */
            idx_t m_next = d * ak_prev - m;
            idx_t d_next = (D - m_next * m_next) / d;
            ak = (a0 + m_next) / d_next;
            m = m_next;
            d = d_next;
        }

        /* Compute the convergent numerator: p_k = a_k * p_{k-1} + p_{k-2} */
        p_cur = p_nm1 * (seq_t)ak + p_nm2;

        /* Shift the state for the next iteration */
        p_nm2 = p_nm1;
        p_nm1 = p_cur;
        ak_prev = ak;
    }

    return p_cur;
}
